fn inSpans(spans: []const Span, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = spans.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (cp < spans[mid].lo) {
            hi = mid;
        } else if (cp > spans[mid].hi) {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

/// The columns one code point occupies.
pub fn codepointWidth(cp: u21) usize {
    if (inSpans(&zero_width, cp)) return 0;
    if (inSpans(&wide, cp)) return 2;
    return 1;
}
